const raw = $input.first().json || {};
const headers = raw.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const expected = $env.N8N_CALENDAR_TOKEN;

if (!expected || auth !== `Bearer ${expected}`) {
  throw new Error('AUTH_FAILED: Bearer token required for raw booking writer');
}

const payload = raw.body || raw;
if (!payload.start || !payload.end) throw new Error('Missing start/end');

const startMs = Date.parse(payload.start);
const endMs = Date.parse(payload.end);
if (Number.isNaN(startMs) || Number.isNaN(endMs)) {
  throw new Error('HORARIO_INVALIDO: start y end deben ser fechas ISO 8601 validas.');
}
if (endMs <= startMs) {
  throw new Error('RANGO_INVALIDO: end debe ser posterior a start.');
}

const tz = 'America/Mexico_City';
const dtf = new Intl.DateTimeFormat('en-CA', {
  timeZone: tz,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  fractionalSecondDigits: 3,
  hour12: false
});

const getParts = (d) => {
  const formatted = dtf.formatToParts(d);
  const map = {};
  for (const p of formatted) map[p.type] = p.value;
  const hour = parseInt(map.hour, 10) % 24;
  const minute = parseInt(map.minute, 10);
  const second = parseInt(map.second, 10);
  const ms = parseInt(map.fractionalSecond || '0', 10);
  const dateStr = `${map.year}-${map.month}-${map.day}`;
  const totalDayMs = ((hour * 60 + minute) * 60 + second) * 1000 + ms;
  return { dateStr, hour, minute, second, ms, totalDayMs };
};

const startParts = getParts(new Date(startMs));
const endParts = getParts(new Date(endMs));

if (startParts.dateStr !== endParts.dateStr) {
  throw new Error(`AGENDA_OUTSIDE_BUSINESS_HOURS: el evento cruza de dia local (${startParts.dateStr} a ${endParts.dateStr} en ${tz}). Toda la reunion debe iniciar y terminar el mismo dia dentro de 08:00 a 20:00.`);
}
if (startParts.totalDayMs < 28800000) {
  const sStr = `${String(startParts.hour).padStart(2, '0')}:${String(startParts.minute).padStart(2, '0')}:${String(startParts.second).padStart(2, '0')}` + (startParts.ms > 0 ? `.${String(startParts.ms).padStart(3, '0')}` : '');
  throw new Error(`AGENDA_OUTSIDE_BUSINESS_HOURS: inicio local ${sStr} esta antes de las 08:00 (${tz}). Ventana permitida: 08:00 a 20:00.`);
}
if (endParts.totalDayMs > 72000000) {
  const eStr = `${String(endParts.hour).padStart(2, '0')}:${String(endParts.minute).padStart(2, '0')}:${String(endParts.second).padStart(2, '0')}` + (endParts.ms > 0 ? `.${String(endParts.ms).padStart(3, '0')}` : '');
  throw new Error(`AGENDA_OUTSIDE_BUSINESS_HOURS: fin local ${eStr} esta despues de las 20:00 (${tz}). Ventana permitida: 08:00 a 20:00.`);
}

let rawRes = payload.resources;
if (typeof rawRes === 'string') {
  try { rawRes = JSON.parse(rawRes); } catch (e) { rawRes = rawRes.split(',').map(s => s.trim()); }
}
if (!Array.isArray(rawRes) || rawRes.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources es obligatorio y debe ser un array no vacio de "calendar" y/o "zoom".');
}
const validSet = new Set(['calendar', 'zoom']);
for (const r of rawRes) {
  if (!validSet.has(r)) {
    throw new Error(`RECURSOS_INVALIDOS: recurso desconocido "${r}". Solo se permite "calendar" y/o "zoom".`);
  }
}
const unique = Array.from(new Set(rawRes));
const resources = ['calendar', 'zoom'].filter(r => unique.includes(r));
if (resources.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources no contiene recursos validos.');
}

const needCalendar = resources.includes('calendar');
const needZoom = resources.includes('zoom');

const calendarId = payload.calendarId || 'ocompudoc@gmail.com';
const contact = payload.contact || {};
const displayName = contact.contactName || payload.contactName || 'Lead IA360';
const wa = contact.contactNumber || payload.contactNumber || '';
const summary = String(payload.summary || '').trim() || `IA360 diagnóstico - ${displayName}`;
const description = String(payload.description || '').trim() || `Reunión IA360 agendada desde WhatsApp. Contacto: ${displayName} (+${wa}).`;

return [{
  json: {
    ...payload,
    resources,
    needCalendar,
    needZoom,
    calendarId,
    displayName,
    wa,
    start: payload.start,
    end: payload.end,
    tz: 'America/Mexico_City',
    summary,
    description,
    zoomMeetingId: null,
    zoomJoinUrl: ''
  }
}];

const norm = $('Normalize Booking').first().json;
const inputData = $input.first() ? $input.first().json : {};
let createData = {};
try { createData = $('Create Zoom Meeting').first()?.json || {}; } catch (e) {}

const createdId = createData.id ? String(createData.id) : (inputData.id ? String(inputData.id) : null);
const createdJoinUrl = createData.join_url || inputData.join_url || '';

let verifyResp = null;
if (inputData.statusCode !== undefined || inputData.body !== undefined) {
  verifyResp = inputData;
} else if (inputData.id && inputData !== createData) {
  verifyResp = inputData;
}

const zoomError = createData.error || inputData.error || (verifyResp && verifyResp.statusCode && Number(verifyResp.statusCode) >= 400 ? `HTTP ${verifyResp.statusCode}` : null);

return [{
  json: {
    ...norm,
    zoomMeetingId: createdId,
    zoomJoinUrl: createdJoinUrl || (verifyResp?.body?.join_url) || '',
    zoom_create: createData,
    zoom_verify: verifyResp,
    zoom_error: zoomError
  }
}];

const raw = $input.first().json;
const meta = $('If Needs Calendar').first().json;
const calendar = raw.calendars?.[meta.calendarId];
const busy = calendar?.busy ?? raw.busy;
const availabilityVerified = Array.isArray(busy) && !raw.error && !calendar?.errors?.length;
const slotFree = availabilityVerified && busy.length === 0;
const calendarError = availabilityVerified === false ? 'calendar_availability_unverified' : (slotFree ? null : 'slot_busy');
return [{ json: { ...meta, slotFree, calendarError } }];

const norm = $('Normalize Booking').first().json;
const resources = norm.resources || [];
const needCalendar = resources.includes('calendar');
const needZoom = resources.includes('zoom');

const components = {};
let allVerified = true;

if (needZoom) {
  let zoomCreate = null;
  let zoomVerify = null;
  let mergeData = null;

  try { mergeData = $('Merge Zoom Info').first()?.json; } catch (e) {}
  try { zoomCreate = $('Create Zoom Meeting').first()?.json; } catch (e) {}
  try { zoomVerify = $('Verify Zoom Meeting').first()?.json; } catch (e) {}

  if (!zoomCreate && mergeData?.zoom_create) zoomCreate = mergeData.zoom_create;
  if (!zoomVerify && mergeData?.zoom_verify) zoomVerify = mergeData.zoom_verify;

  const createdId = zoomCreate?.id ? String(zoomCreate.id) : (mergeData?.zoomMeetingId ? String(mergeData.zoomMeetingId) : null);
  const createdJoinUrl = zoomCreate?.join_url || mergeData?.zoomJoinUrl || null;
  const createError = zoomCreate?.error?.message || zoomCreate?.error || null;

  const verifyData = zoomVerify?.body || zoomVerify;
  const verifyStatusCode = Number(zoomVerify?.statusCode || (verifyData?.id ? 200 : 0));
  const verifyId = verifyData?.id ? String(verifyData.id) : null;
  const verifyStartTime = verifyData?.start_time || '';
  const verifyDuration = verifyData?.duration !== undefined ? Number(verifyData.duration) : null;
  const verifyTopic = String(verifyData?.topic || '').trim();
  const verifyJoinUrl = verifyData?.join_url || createdJoinUrl;
  const verifyError = zoomVerify?.error?.message || zoomVerify?.error || (verifyStatusCode >= 400 ? `HTTP ${verifyStatusCode}` : null);

  const startMatch = Boolean(verifyStartTime && new Date(verifyStartTime).getTime() === new Date(norm.start).getTime());
  const expectedDuration = Math.max(1, Math.ceil((new Date(norm.end).getTime() - new Date(norm.start).getTime()) / 60000));
  const durationMatch = verifyDuration === expectedDuration;
  const topicMatch = Boolean(Boolean(norm.summary) === false || verifyTopic === String(norm.summary).trim());

  const zoomVerified = Boolean(
    createdId &&
    verifyId &&
    verifyId === createdId &&
    zoomVerify?.statusCode === 200 &&
    durationMatch &&
    startMatch &&
    topicMatch &&
    Boolean(verifyError) === false
  );

  if (zoomVerified) {
    components.zoom = {
      state: 'verified',
      id: createdId,
      join_url: verifyJoinUrl || createdJoinUrl
    };
  } else {
    allVerified = false;
    const hasId = Boolean(createdId || verifyId);
    components.zoom = {
      state: hasId ? 'uncertain' : 'failed',
      id: createdId || verifyId || undefined,
      join_url: (createdJoinUrl || verifyJoinUrl) || undefined,
      error: verifyError || createError || (hasId ? 'Zoom meeting verification mismatch or GET failed' : 'Zoom meeting creation failed')
    };
  }
}

if (needCalendar) {
  let calCreate = null;
  let calVerify = null;
  let slotError = null;
  try { slotError = $('Assert Slot Free').first()?.json?.calendarError; } catch (e) {}

  try { calCreate = $('Create Calendar Event').first()?.json; } catch (e) {}
  try { calVerify = $('Verify Calendar Event Exists').first()?.json; } catch (e) {}

  const createdCalId = calCreate?.id ? String(calCreate.id) : null;
  const createCalError = calCreate?.error?.message || calCreate?.error || null;

  const verifyCalData = calVerify?.body || calVerify;
  const verifyCalId = verifyCalData?.id ? String(verifyCalData.id) : null;
  const verifyCalStatus = String(verifyCalData?.status || '').toLowerCase();
  const verifyCalError = calVerify?.error?.message || calVerify?.error || (verifyCalData?.error?.message || null);
  const readStart = verifyCalData?.start?.dateTime || verifyCalData?.start?.date || '';
  const readEnd = verifyCalData?.end?.dateTime || verifyCalData?.end?.date || '';
  const readSummary = String(verifyCalData?.summary || '').trim();

  const idMatch = Boolean(createdCalId && verifyCalId && verifyCalId === createdCalId);
  const notCancelled = Boolean(verifyCalStatus && verifyCalStatus !== 'cancelled');
  const startMatch = Boolean(readStart && new Date(readStart).toISOString() === new Date(norm.start).toISOString());
  const endMatch = Boolean(readEnd && new Date(readEnd).toISOString() === new Date(norm.end).toISOString());
  const titleMatch = Boolean(Boolean(norm.summary) === false || readSummary === String(norm.summary).trim());

  const calVerified = Boolean(idMatch && notCancelled && startMatch && endMatch && titleMatch && Boolean(verifyCalError) === false && Boolean(createCalError) === false);

  if (calVerified) {
    components.calendar = {
      state: 'verified',
      id: createdCalId,
      htmlLink: verifyCalData?.htmlLink || calCreate?.htmlLink || undefined
    };
  } else {
    allVerified = false;
    const hasCalId = Boolean(createdCalId || verifyCalId);
    components.calendar = {
      state: hasCalId ? 'uncertain' : 'failed',
      id: createdCalId || verifyCalId || undefined,
      error: slotError || verifyCalError || createCalError || (hasCalId ? (verifyCalStatus === 'cancelled' ? 'Calendar event is cancelled' : 'Calendar event slot/title mismatch or readback failed') : 'READBACK_FAILED: Google Calendar event was not verified by readback')
    };
  }
}

const verified = Boolean(allVerified && resources.length > 0);

return [{
  json: {
    ok: verified,
    verified,
    status: verified ? 'booked' : 'uncertain',
    state: verified ? 'agendada' : 'incierta',
    resources,
    components,
    start: norm.start,
    end: norm.end,
    summary: norm.summary,
    contactName: norm.displayName,
    contactNumber: norm.wa,
    calendarEventId: components.calendar?.id || null,
    calendarHtmlLink: components.calendar?.htmlLink || null,
    zoomMeetingId: components.zoom?.id || null,
    zoomJoinUrl: components.zoom?.join_url || null
  }
}];
